fun formatShutterSpeed(exposureTimeNs: Long): String {
    val seconds = exposureTimeNs / 1_000_000_000


    val standardSpeeds = intArrayOf(
        8000, 4000, 2000, 1000, 500, 250, 125, 60, 30, 15, 8, 4, 2, 1
    )


    if (seconds >= 30.0) {
        return "${seconds.toLong()}s"
    }


    if (seconds >= 1.0) {
        return "${seconds.toLong()}s"
    }


    if (seconds <= 0.000125) { 
        return "1/8000s"
    }


    var bestIndex = 0
    var bestDiff = Double.MAX_VALUE

    for (i in standardSpeeds.indices) {
        val speedSec = 1.0 / standardSpeeds[i]
        val diff = Math.abs(speedSec - seconds)
        if (diff < bestDiff) {
            bestDiff = diff
            bestIndex = i
        }
    }

    val denom = standardSpeeds[bestIndex]



    if (bestDiff < 0.02) {
        return "1/${denom}s"
    } else {

        return "${seconds.toStringAsFixed(1)}s"
    }
}

